fn verify_effective_rights(path: &[u16], sid: PSID, required: u32, forbidden: u32) -> Result<()> {
    let (acl, descriptor) = get_dacl(path)?;
    let mut rights = 0u32;
    let status = unsafe { GetEffectiveRightsFromAclW(acl, &trustee_for_sid(sid), &mut rights) };
    if status != ERROR_SUCCESS || rights & required != required || rights & forbidden != 0 {
        bail!("foreign-process sandbox artifact rights are incomplete or excessive");
    }
    drop(descriptor);
    Ok(())
}

fn get_dacl(path: &[u16]) -> Result<(*mut ACL, LocalAllocation)> {
    let mut acl = null_mut();
    let mut descriptor: PSECURITY_DESCRIPTOR = null_mut();
    let status = unsafe {
        GetNamedSecurityInfoW(
            path.as_ptr(),
            SE_FILE_OBJECT,
            DACL_SECURITY_INFORMATION,
            null_mut(),
            null_mut(),
            &mut acl,
            null_mut(),
            &mut descriptor,
        )
    };
    if status != ERROR_SUCCESS || descriptor.is_null() || acl.is_null() {
        bail!("foreign-process sandbox artifact ACL is unavailable");
    }
    Ok((acl, LocalAllocation(descriptor as HLOCAL)))
}

